import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import { NumberPicker } from '@alifd/next';

function App() {
  // Initialize with the problematic float
  const [value, setValue] = useState(4.02);

  const handleChange = (val, e) => {
    console.log('onChange value:', val, 'triggerType:', e.triggerType);
    setValue(val);
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>Safari Float Precision Bug Repro</h3>
      <NumberPicker
        // defaultValue can be replaced by value to control fully
        value={value}
        step={0.01}
        precision={2}    // try toggling this prop on/off
        onChange={handleChange}
      />
    </div>
  );
}

// Assumes you have a <div id="root"></div> in your HTML
ReactDOM.render(<App />, document.getElementById('root'));
